import { z } from 'zod';

const key = z.string().regex(/^[a-z0-9_]+$/i);
const point = z.tuple([z.number().min(-90).max(90), z.number().min(-180).max(180)]);

/** Shape of data/map/titles.yaml (generated by tools/build_titles.py): fallback areas, counties and duchies. */
export const generatedTitlesSchema = z.object({
  areas: z.record(key, z.string()),
  counties: z.array(z.tuple([key, z.string(), key, z.array(key).min(1)])),
  duchies: z.array(z.tuple([key, z.string(), key, z.array(key).min(1)])),
});

/** Shape of data/content/titles.yaml: hand-made kingdoms (areas), empires (regions) and hegemonies. */
export const upperTitlesSchema = z.object({
  fill: z.array(z.array(point).min(3)).default([]),
  kingdoms: z.array(z.object({ key, name: z.string().min(1), area: z.array(z.array(point).min(3)).default([]) })),
  empire_fill: z.array(z.array(point).min(3)).default([]),
  empires: z.array(z.object({
    key,
    name: z.string().min(1),
    area: z.array(z.array(point).min(3)).default([]),
    kingdoms: z.array(key).default([]),
  })),
  hegemonies: z.array(z.object({
    key,
    name: z.string().min(1),
    hindu_name: z.string().optional(),
    description: z.string().default(''),
    de_jure: z.boolean().default(false),
    empires: z.array(key).min(1),
  })).default([]),
});

export type GeneratedTitles = z.infer<typeof generatedTitlesSchema>;
export type UpperTitles = z.infer<typeof upperTitlesSchema>;
